 "content": "def transform(grid):
    """Copy the embedded length-three color motif onto each isolated marker."""
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]

    # Find the straight, contiguous 3-cell exemplar (horizontal or vertical).
    motif = None
    exemplar = set()
    for r in range(h):
        for c in range(w):
            if c + 2 < w and all(grid[r][c + k] != background for k in range(3)):
                motif = [grid[r][c + k] for k in range(3)]
                exemplar = {(r, c + k) for k in range(3)}
                break
        if motif is not None:
            break
    if motif is None:
        for r in range(h - 2):
            for c in range(w):
                if all(grid[r + k][c] != background for k in range(3)):
                    motif = [grid[r + k][c] for k in range(3)]
                    exemplar = {(r + k, c) for k in range(3)}
                    break
            if motif is not None:
                break
    if motif is None:
        return [row[:] for row in grid]

    # The center motif color is replaced by marker cells; other colors in the
    # motif identify the exemplar rather than marker positions.
    motif_colors = set(motif)
    marker_colors = [color for color in counts if color != background and color not in motif_colors]
    if not marker_colors:
        return [row[:] for row in grid]
    marker_color = max(marker_colors, key=lambda color: counts[color])
    markers = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] == marker_color and (r, c) not in exemplar]

    out = [row[:] for row in grid]
    for r, c in markers:
        for offset, value in enumerate(motif):
            delta = offset - 1
            rr, cc = (r, c + delta) if exemplar and len({x for x, _ in exemplar}) == 1 else (r + delta, c)
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = value
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
